/**
 * The Nebius documentation catalog (docs/reference/nebius-docs.json, generated by `make docs-catalog`) as the portal
 * reads it, and the portal's coverage stated against it (W1-P26, #11): which documented services the portal reads,
 * through which calls, and for each one it does not read, why and what that leaves out.
 */
import type { CapabilityStatus } from './api';

export interface NebiusDocsSection {
  /** The catalog section: the first path segment of a docs page ("compute", "kubernetes"; "/" for the home page). */
  name: string;
  pages: number;
  /** A generated reference (CLI, REST API, legal): the catalog lists its landing page only. */
  referenceOnly: boolean;
}

export interface NebiusDocsPage {
  /** The docs path, "/compute/clusters/gpu". */
  path: string;
  title: string;
  section: string;
}

export interface NebiusDocsResponse {
  /** The day the catalog was generated. */
  generated: string;
  source: string;
  sections: NebiusDocsSection[];
  pages: NebiusDocsPage[];
  keyPages: { path: string; why: string }[];
  /** The local page mirror (.cache/nebius-docs, written by `make docs-catalog`) is present: pages open in the portal. */
  mirror: boolean;
}

export interface NebiusDocsPageResponse {
  path: string;
  title: string;
  /** The page on docs.nebius.com. */
  url: string;
  headings: { text: string; anchor: string }[];
  /** The mirrored Markdown, when the local mirror has the page. */
  markdown?: string;
  mirrored: boolean;
}

export const DOCS_ORIGIN = 'https://docs.nebius.com';

/** The section of a docs path: "/compute/clusters/gpu" → "compute"; "/" → "/". */
export const docsSection = (path: string) => path.split('/').filter(Boolean)[0] ?? '/';

/** The public URL of a docs path (and section anchor). */
export const docsUrl = (path: string, anchor?: string) => `${DOCS_ORIGIN}${path === '/' ? '/' : path}${anchor ? `#${anchor}` : ''}`;

/** Key pages whose note names the recipe ("GPU clusters and InfiniBand fabrics (R3)"); R1 never matches R12. */
export const recipeKeyPages = (keyPages: { path: string; why: string }[], recipe: string) => keyPages.filter(k => new RegExp(`\\b${recipe}\\b`, 'i').test(k.why));

/** The portal page for a docs path (the Nebius docs page with it open). */
export const docsHref = (path: string) => `/nebius-docs?page=${encodeURIComponent(path)}`;

/** `soperator`: only the Kubernetes API calls of clusters identified as Soperator clusters read the section. */
type Source = { calls: RegExp[]; how?: string; soperator?: true };
type Kind =
  | ({ kind: 'service' } & Source)
  | { kind: 'not-read'; reason: string; impact: string }
  | { kind: 'reference'; reason: string };

const REFERENCE = 'Documentation (tools, APIs, reference): no service of its own to read.';

/**
 * How each catalog section relates to what the portal reads. Service sections name the capability calls that read
 * them (CapabilityStatus.id); a section the portal does not read says why and what is left out. Kept next to the
 * catalog's section list: a section missing here is reported as "not classified", never as read.
 */
export const DOCS_SECTIONS: Record<string, Kind> = {
  compute: { kind: 'service', calls: [/^compute\./, /^capacity\./, /^maintenance\./] },
  kubernetes: { kind: 'service', calls: [/^mk8s\./, /^k8s\.cluster:/] },
  vpc: { kind: 'service', calls: [/^vpc\./] },
  'object-storage': { kind: 'service', calls: [/^storage\./] },
  'container-registry': { kind: 'service', calls: [/^registry\./] },
  postgresql: { kind: 'service', calls: [/^msp\.postgresql$/] },
  mlflow: { kind: 'service', calls: [/^msp\.mlflow$/] },
  serverless: { kind: 'service', calls: [/^ai\./] },
  tunnels: { kind: 'service', calls: [/^tunnel\./] },
  kms: { kind: 'service', calls: [/^kms\./] },
  mysterybox: { kind: 'service', calls: [/^mysterybox\./] },
  iam: { kind: 'service', calls: [/^iam\./] },
  overview: { kind: 'service', calls: [/^quotas\./], how: 'quotas and limits' },
  'signup-billing': { kind: 'service', calls: [/^billing\./], how: 'the calculator, pricing policies and the billing export' },
  observability: { kind: 'service', calls: [/^monitoring\./, /^logs\./], how: 'metrics and logs' },
  'audit-logs': { kind: 'service', calls: [/^audit\./] },
  'slurm-soperator': { kind: 'service', calls: [/^k8s\.cluster:/], soperator: true, how: 'a Soperator cluster is read as its Managed Kubernetes cluster' },
  applications: {
    kind: 'not-read',
    reason: 'The portal makes no call for applications.',
    impact:
      'Standalone applications are not listed. An application deployed on a virtual machine or on a Managed Kubernetes cluster shows as that VM or those workloads, not as an application.',
  },
  'ai-services': { kind: 'reference', reason: 'An index of Serverless AI, MLflow and Applications: covered under those sections.' },
  '/': { kind: 'reference', reason: 'The documentation home page.' },
  '3p-integrations': { kind: 'reference', reason: 'Third-party tools that run on Nebius: nothing of Nebius to read.' },
  changelog: { kind: 'reference', reason: 'The platform changelog.' },
  cli: { kind: 'reference', reason: REFERENCE },
  'developer-tools': { kind: 'reference', reason: REFERENCE },
  'docs-ai': { kind: 'reference', reason: REFERENCE },
  'grpc-api': { kind: 'reference', reason: REFERENCE },
  legal: { kind: 'reference', reason: 'Legal terms.' },
  'rest-api': { kind: 'reference', reason: REFERENCE },
  sdk: { kind: 'reference', reason: REFERENCE },
  security: { kind: 'reference', reason: 'Security practices and encryption: no service of its own to read.' },
  'terraform-provider': { kind: 'reference', reason: REFERENCE },
  tutorials: { kind: 'reference', reason: 'Tutorials.' },
};

export interface SectionCoverage {
  section: string;
  pages: number;
  /** read: a call answered at the last sync; failing: called, none answered; not-read: no call; reference: docs only. */
  state: 'read' | 'failing' | 'not-read' | 'reference' | 'not-classified';
  calls: { ok: number; total: number; ids: string[] };
  how?: string;
  reason?: string;
  impact?: string;
}

/**
 * Coverage stated against the docs catalog (W1-P26): every catalog section, with the calls that read it.
 * `soperatorClusterIds` are the Managed Kubernetes clusters identified as Soperator clusters (IntegrationsResponse):
 * Slurm is read only through theirs, never through any cluster that answers.
 */
export function docsCoverage(
  sections: NebiusDocsSection[],
  capabilities: Pick<CapabilityStatus, 'id' | 'state'>[],
  opts: { soperatorClusterIds?: string[] } = {},
): { rows: SectionCoverage[]; summary: string } {
  const soperator = new Set((opts.soperatorClusterIds ?? []).map(id => `k8s.cluster:${id}`));
  const rows: SectionCoverage[] = sections.map(s => {
    const k = DOCS_SECTIONS[s.name];
    if (!k) return { section: s.name, pages: s.pages, state: 'not-classified', calls: { ok: 0, total: 0, ids: [] }, reason: 'Not classified by the portal yet (a new docs section).' };
    if (k.kind !== 'service') return { section: s.name, pages: s.pages, state: k.kind, calls: { ok: 0, total: 0, ids: [] }, reason: k.reason, ...(k.kind === 'not-read' ? { impact: k.impact } : {}) };
    const mine = capabilities.filter(c => k.calls.some(r => r.test(c.id)) && (!k.soperator || soperator.has(c.id)));
    // Schema drift answered (in a shape the portal partly reads): read, as the health records count it.
    const ok = mine.filter(c => c.state === 'ok' || c.state === 'schema-drift').length;
    const calls = { ok, total: mine.length, ids: mine.map(c => c.id) };
    if (!mine.length && k.soperator) return { section: s.name, pages: s.pages, state: 'not-read', calls, how: k.how, reason: 'No Soperator cluster in scope.', impact: 'No Slurm cluster is shown.' };
    if (!mine.length) return { section: s.name, pages: s.pages, state: 'not-read', calls, how: k.how, reason: 'No call for it in this deployment (not set up or not in scope).', impact: 'Its resources are not shown.' };
    if (!ok) {
      const states = [...new Set(mine.map(c => c.state.replace(/-/g, ' ')))].join(', ');
      return { section: s.name, pages: s.pages, state: 'failing', calls, how: k.how, reason: `Called, none answered at the last sync (${states}).`, impact: 'Its resources are missing or stale until a call answers.' };
    }
    return { section: s.name, pages: s.pages, state: 'read', calls, how: k.how };
  });
  const service = rows.filter(r => r.state !== 'reference');
  const read = service.filter(r => r.state === 'read');
  const gaps = service.filter(r => r.state !== 'read').map(r => r.section);
  const summary = `Reads ${read.length} of ${service.length} service sections of the Nebius docs catalog${gaps.length ? `; not read: ${gaps.join(', ')}` : ''}.`;
  return { rows, summary };
}
